     (void) i_ins;
     (void) config;

+    /*
+     * When the plugin is configured to operate in 'chunk' mode, the whole raw
+     * event chunk is passed to the user callback as-is (no per-record
+     * iteration or conversion).
+     */
+    if (ctx->data_mode == FLB_DATA_MODE_CHUNK) {
+        data_for_user = flb_malloc(event_chunk->size);
+        if (!data_for_user) {
+            flb_errno();
+            FLB_OUTPUT_RETURN(FLB_ERROR);
+        }
+
+        memcpy(data_for_user, event_chunk->data, event_chunk->size);
+        data_size = event_chunk->size;
+
+        /* Invoke user callback with the entire chunk */
+        ctx->cb_func(data_for_user, data_size, ctx->cb_data);
+
+        FLB_OUTPUT_RETURN(FLB_OK);
+    }
